int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, guint8 *drep, char **data, int hf_name) {
    int original_offset = offset;
    int length = 0;
    char *utf8_str = NULL;

    /* Adjust offset to be even */
    if (offset % 2 != 0) {
        offset++;
    }

    /* Get the length of the remaining data in the tvb */
    length = tvb_reported_length_remaining(tvb, offset);

    /* If there is data remaining, dissect it as UTF-16 string */
    if (length > 0) {
        utf8_str = tvb_get_unicode_string(tvb, offset, length, TRUE);
        if (utf8_str != NULL) {
            proto_tree_add_string(tree, hf_name, tvb, original_offset, length, utf8_str);
            if (data != NULL) {
                *data = utf8_str;
            }
            offset += length;
        }
    }

    return offset;
}
